<section class="admin-panel"><h2>Políticas de descuento adicional</h2><p class="admin-panel-copy">Definen el límite operativo del vendedor; una cotización futura deberá solicitar aprobación cuando lo exceda.</p><?php if($capabilities['discount_policies.manage']??false):?><form class="admin-inline-form" method="post" action="/admin/discount-policies/save"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><label class="admin-field"><span>Sucursal sin política</span><select name="branch_id"><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>"><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Límite %</span><input name="rate" required></label><button class="admin-secondary-button">Registrar inactiva</button></form><?php endif?><ul class="admin-card-list"><?php foreach($policies as$p):?><li><span><strong><?= e($p['branch_name']) ?></strong><small><?= (int)$p['is_active']===1?'Activa':'Inactiva; aún no rige' ?></small></span><span class="admin-status <?= (int)$p['is_active']===1?'is-active':'' ?>"><?= e($p['seller_limit_rate']) ?> %</span><?php if($capabilities['discount_policies.manage']??false):?><form class="admin-inline-form" method="post" action="/admin/discount-policies/save"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="branch_id" value="<?= e($p['branch_id']) ?>"><input type="hidden" name="lock_version" value="<?= e($p['lock_version']) ?>"><label class="admin-field"><span>Nuevo límite %</span><input name="rate" value="<?= e($p['seller_limit_rate']) ?>" required></label><button class="admin-secondary-button">Actualizar</button></form><form method="post" action="/admin/discount-policies/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($p['id']) ?>"><input type="hidden" name="branch_id" value="<?= e($p['branch_id']) ?>"><input type="hidden" name="lock_version" value="<?= e($p['lock_version']) ?>"><